"                           {(() => {
                              const chargeDetails = Array.isArray(previewReceipt.charge_details) ? previewReceipt.charge_details : (typeof previewReceipt.charge_details === 'string' ? JSON.parse(previewReceipt.charge_details || '[]') : []);
                              if (chargeDetails.length > 0) {
                                return chargeDetails.map((c, idx) => (
                                  <div key={`charge-${idx}`} className="flex justify-between items-center py-0.5 border-b border-[#30363d]/50">
                                     <span className="text-gray-500">{c.name || 'Charge'}:</span>
                                     <span className="font-bold">Rs {parseFloat(c.amount || c.value || 0).toFixed(2)}</span>
                                  </div>
                                ));
                              } else if (parseFloat(previewReceipt.delivery_charge || 0) > 0) {
                                return (
                                  <div className="flex justify-between items-center py-0.5 border-b border-[#30363d]/50">
                                     <span className="text-gray-500">Delivery Charges:</span>
                                     <span className="font-bold">Rs {parseFloat(previewReceipt.delivery_charge).toFixed(2)}</span>
                                  </div>
                                );
                              }
                              return null;
                           })()}"
